LESSON_DB.english_hl.m0 = {
  0: {emoji:"✍️", subtitle:"Grade 10 · The jobs words do in a sentence",
    illusText:"“Book your Gautrain seat” and “read the book” — same word, different job.",
    hook:{title:"Book the book", body:"On the Gautrain app you <strong>book</strong> a seat. In class you read a <strong>book</strong>. The spelling is the same, but in the first sentence it's an action (a verb) and in the second it's a thing (a noun). A word's part of speech depends on the job it does in <em>this</em> sentence — not on the word itself."},
    intro:"English has eight main <strong>parts of speech</strong>: <strong>nouns</strong> (people, places, things, ideas), <strong>pronouns</strong> (words that replace nouns: she, they, it), <strong>verbs</strong> (actions or states), <strong>adjectives</strong> (describe nouns), <strong>adverbs</strong> (describe verbs, adjectives or other adverbs), <strong>prepositions</strong> (show position or relationship: in, on, under, before), <strong>conjunctions</strong> (join words or clauses: and, but, because) and <strong>interjections</strong> (sudden feelings: Wow! Eish!). Articles and determiners (a, the, this, my) introduce nouns.",
    concepts:[
      {t:"green", title:"🏷️ Naming words", body:"Nouns can be proper (Durban, Siya), common (taxi), collective (a <em>team</em> of players) or abstract (freedom, fear). Pronouns stand in for them so we don't repeat ourselves."},
      {t:"teal", title:"🏃 Doing and describing", body:"Verbs show action or state. Adjectives describe nouns (a <em>noisy</em> crowd). Adverbs describe how, when, where or how much (cheered <em>loudly</em>, arrived <em>early</em>)."},
      {t:"gold", title:"🔗 Joining words", body:"Prepositions link a noun to the rest of the sentence (under the bridge). Conjunctions join ideas (I stayed home <em>because</em> it rained)."},
    ],
    examples:[
      {title:"Label the sentence", body:"“Thandi quickly packed her lunch before the bus arrived.”", answer:"Thandi = proper noun · quickly = adverb · packed = verb · her = possessive determiner · lunch = noun · before = conjunction · the = article · bus = noun · arrived = verb."},
      {title:"Same word, three jobs", body:"“Bafana Bafana played <u>well</u>.” / “The <u>well</u> dried up.” / “<u>Well</u>! That was close.”", answer:"Adverb (how they played) · noun (a thing) · interjection (a sudden feeling)."},
      {title:"Fix the error", body:"“She sings good.”", answer:"<em>Good</em> is an adjective, but it describes the verb <em>sings</em>, so we need an adverb: <strong>She sings well.</strong>"},
    ],
    mistakes:["Thinking a word always belongs to one class — “light” can be a noun, a verb or an adjective.","Using an adjective where an adverb is needed: “He drives careless” → <strong>carelessly</strong>.","Calling “and”, “but” and “because” prepositions — they are conjunctions."],
    callout:{title:"Where you'll use this", body:"Paper 1 language questions ask you to identify the part of speech of an underlined word, and knowing the jobs helps you fix errors in your own essays."},
    activity:"Label every word: “Wow, the noisy crowd cheered loudly for Siya.”",
    activityAnswer:"Wow = interjection · the = article · noisy = adjective · crowd = collective noun · cheered = verb · loudly = adverb · for = preposition · Siya = proper noun.",
    examTip:"Be specific when you can: “abstract noun” or “adverb of manner” shows the marker you really know it. Always read the word inside its sentence before you decide.",
    keyterms:[{w:"Noun",d:"Names a person, place, thing or idea"},{w:"Adverb",d:"Describes a verb, adjective or another adverb — how, when, where"},{w:"Conjunction",d:"Joins words or clauses (and, but, because, although)"}],
    quiz:[
      {q:"In “Book your Gautrain ticket online”, <em>book</em> is a:",opts:["Noun","Verb","Adjective","Adverb"],a:1,et:"It's an action you do, so it's a verb."},
      {q:"Which sentence is correct?",opts:["She did good in the test.","She did well in the test.","She done well in the test.","She did more good in the test."],a:1,et:"<em>Well</em> is the adverb describing how she did."},
      {q:"In “We stayed inside because it rained”, <em>because</em> is a:",opts:["Preposition","Conjunction","Adverb","Pronoun"],a:1,et:"It joins two clauses, so it's a conjunction."},
    ],
    conclusion:"Parts of speech are about jobs, not labels stuck to words. Ask what the word is doing in this sentence and you'll get it right."},

  1: {emoji:"🧱", subtitle:"Grade 10–11 · Simple, compound and complex sentences",
    illusText:"A sentence needs a subject, a verb and a complete thought — everything else is building on that.",
    hook:{title:"The run-on WhatsApp", body:"“we got to school the gate was locked nobody told us it was a public holiday” — three complete ideas crammed into one line with no punctuation. Read aloud, it's breathless and confusing. Split or join the ideas properly and it makes sense: <strong>We got to school, but the gate was locked. Nobody had told us it was a public holiday.</strong>"},
    intro:"A <strong>sentence</strong> has a subject, a finite verb and a complete thought. A <strong>clause</strong> is a group of words with a subject and verb. A <strong>main clause</strong> can stand alone; a <strong>subordinate clause</strong> (starting with because, although, when, if, who, which…) cannot. <strong>Simple</strong> sentences have one main clause. <strong>Compound</strong> sentences join two main clauses with a coordinating conjunction (for, and, nor, but, or, yet, so) or a semicolon. <strong>Complex</strong> sentences have a main clause plus at least one subordinate clause.",
    concepts:[
      {t:"green", title:"🧩 Main vs subordinate clauses", body:"“Although it was raining” can't stand alone — it needs “the match continued” to finish the thought."},
      {t:"teal", title:"🔗 Joining correctly", body:"Two main clauses need a conjunction, a semicolon or a full stop between them. A comma alone creates a <strong>comma splice</strong>."},
      {t:"gold", title:"🔄 Active and passive voice", body:"Active: <em>The learners cleaned the classroom.</em> Passive: <em>The classroom was cleaned by the learners.</em> Keep the same tense when you change voice."},
    ],
    examples:[
      {title:"Classify", body:"“Although it was raining, the match continued.”", answer:"<strong>Complex</strong>: subordinate clause “Although it was raining” + main clause “the match continued”."},
      {title:"Fix the run-on", body:"“We got to school the gate was locked.”", answer:"<strong>We got to school, but the gate was locked.</strong> (or two sentences, or a semicolon)."},
      {title:"Change to passive", body:"“The principal will announce the results.”", answer:"<strong>The results will be announced by the principal.</strong> — future tense kept."},
    ],
    mistakes:["Comma splices: “I studied hard, I passed.”","Fragments: “Because I was late.” on its own is not a sentence.","Changing the tense when converting to passive (“is eating” must become “is being eaten”)."],
    callout:{title:"Why it matters", body:"Varying simple, compound and complex sentences makes your essays sound mature — and fixing run-ons and fragments removes easy language penalties."},
    activity:"Combine into one complex sentence: “The taxi was full. We waited for the next one.”",
    activityAnswer:"“<strong>Because the taxi was full, we waited for the next one.</strong>” or “We waited for the next one because the taxi was full.”",
    examTip:"In voice-change questions, underline the verb first and identify its tense. The passive must keep that tense exactly.",
    keyterms:[{w:"Clause",d:"A group of words with a subject and a verb"},{w:"Complex sentence",d:"A main clause plus at least one subordinate clause"},{w:"Passive voice",d:"The receiver of the action becomes the subject"}],
    quiz:[
      {q:"“I studied hard, I passed.” is an example of a:",opts:["Complex sentence","Comma splice","Simple sentence","Fragment"],a:1,et:"Two main clauses joined only by a comma."},
      {q:"The passive of “The principal will announce the results” is:",opts:["The results are announced by the principal.","The results will be announced by the principal.","The results were announced by the principal.","The principal will be announced by the results."],a:1,et:"Future tense: will be + past participle."},
      {q:"Which is a complex sentence?",opts:["I ran.","I ran and she walked.","I ran because I was late.","Run!"],a:2,et:"“because I was late” is a subordinate clause."},
    ],
    conclusion:"Know your clauses and you control your sentences — no more run-ons, no more fragments, and a style that flows."},

  2: {emoji:"❗", subtitle:"Grade 10–12 · The small marks that change meaning",
    illusText:"“Let's eat, Gogo!” and “Let's eat Gogo!” — one comma saves Gogo.",
    hook:{title:"Let's eat, Gogo", body:"“Let's eat, Gogo!” invites your grandmother to supper. “Let's eat Gogo!” is a horror story. A spaza sign reading “Cold drink's R10” has an apostrophe where none belongs. Punctuation isn't decoration — it changes meaning, and markers notice every slip."},
    intro:"<strong>Full stops</strong> end statements. <strong>Commas</strong> separate items in a list, follow an introductory clause and mark off extra information. <strong>Apostrophes</strong> show possession (Thabo's bag, the learners' bags) or a missing letter (it's = it is). <strong>Colons</strong> introduce a list or explanation; <strong>semicolons</strong> join two closely related main clauses. South African English uses <strong>British spelling</strong>: colour, centre, programme, travelled, practice (noun) / practise (verb).",
    concepts:[
      {t:"green", title:"✏️ Commas that change meaning", body:"“Sipho, my brother plays soccer” speaks <em>to</em> Sipho. “Sipho, my brother, plays soccer” tells you Sipho <em>is</em> my brother."},
      {t:"teal", title:"’ Apostrophes", body:"Singular owner: the learner's book. Plural owner ending in s: the learners' books. Plurals never need an apostrophe: tomatoes, not tomato's."},
      {t:"gold", title:"🔀 Confusing pairs", body:"its / it's · their / there / they're · your / you're · affect (verb) / effect (noun) · could <em>have</em>, never “could of”."},
    ],
    examples:[
      {title:"One owner or many?", body:"“The learner's books” vs “The learners' books”.", answer:"First: books belonging to <strong>one</strong> learner. Second: books belonging to <strong>several</strong> learners."},
      {title:"its or it's?", body:"“The school changed it's uniform.”", answer:"<strong>its</strong> — belonging to the school. <em>It's</em> only ever means “it is” or “it has”."},
      {title:"Semicolon", body:"“I was exhausted I went to bed early.”", answer:"<strong>I was exhausted; I went to bed early.</strong> Two related main clauses."},
    ],
    mistakes:["Using an apostrophe to make a plural (“R10 per tomato's”).","Writing “could of” instead of “could have”.","Mixing British and American spelling (color/colour) in the same essay."],
    callout:{title:"In the exam", body:"Paper 1 has editing questions where you correct punctuation and spelling, and every writing rubric includes language — careless punctuation costs marks everywhere."},
    activity:"Correct the sentence: “Their going to the grade 12 farewell in the schools hall on friday”",
    activityAnswer:"<strong>They're going to the Grade 12 farewell in the school's hall on Friday.</strong> (They're = they are; school's = belonging to the school; capital G and F.)",
    examTip:"In editing questions, each error is usually worth one mark: find it, correct it, and don't rewrite the rest of the sentence.",
    keyterms:[{w:"Apostrophe of possession",d:"Shows ownership: Lerato's phone"},{w:"Semicolon",d:"Joins two closely related main clauses"},{w:"Comma splice",d:"Two main clauses joined only by a comma"}],
    quiz:[
      {q:"Which is correct?",opts:["The dog wagged it's tail.","The dog wagged its tail.","The dog wagged its' tail.","The dog wagged it tail."],a:1,et:"<em>Its</em> shows possession; <em>it's</em> means it is."},
      {q:"“The girls' bags” means:",opts:["Bags belonging to one girl","Bags belonging to more than one girl","One bag belonging to a girl","It is a spelling mistake"],a:1,et:"The apostrophe after the s shows a plural owner."},
      {q:"Which uses a semicolon correctly?",opts:["I was tired; so I slept.","I was tired; I went to bed early.","I was; tired I went to bed.","I; was tired."],a:1,et:"Two complete, related main clauses."},
    ],
    conclusion:"Punctuation is how readers hear your voice on the page. Get the small marks right and your meaning comes through clearly."},

  3: {emoji:"🎭", subtitle:"Grade 10–12 · Saying more than the words say",
    illusText:"Durban in December isn't really an oven — but you know exactly what the speaker means.",
    hook:{title:"Is Durban really an oven?", body:"“Durban in December is an oven.” Nobody thinks the city is a kitchen appliance — but you instantly feel the heat. That's <strong>figurative language</strong>: words used beyond their literal meaning to create a picture or feeling. Adverts, songs, speeches and poems are full of it, and Paper 1 and Paper 2 will ask you to name it and explain its effect."},
    intro:"A <strong>simile</strong> compares using like or as (roared like a lion). A <strong>metaphor</strong> says one thing <em>is</em> another (Durban is an oven). <strong>Personification</strong> gives human qualities to non-human things. <strong>Hyperbole</strong> is deliberate exaggeration. <strong>Onomatopoeia</strong> imitates sounds (sizzle, hoot). <strong>Alliteration</strong> repeats initial consonant sounds. An <strong>oxymoron</strong> joins opposites (deafening silence). A <strong>euphemism</strong> softens something unpleasant (passed away). <strong>Irony</strong> is a gap between what is said or expected and what is meant or happens.",
    concepts:[
      {t:"green", title:"🔁 Comparisons", body:"Simile, metaphor and personification all compare. Ask: what two things are being compared, and what do they have in common?"},
      {t:"teal", title:"🔊 Sound devices", body:"Alliteration, onomatopoeia and assonance make lines memorable and create mood — think of the rhythm in a jingle or a praise poem."},
      {t:"gold", title:"⚖️ Exaggeration and contrast", body:"Hyperbole, oxymoron, irony and euphemism play with expectations to create humour, emphasis or sympathy."},
    ],
    examples:[
      {title:"Identify and explain", body:"“The minibus taxi roared like a lion.”", answer:"<strong>Simile</strong>: the engine's noise is compared to a lion's roar, suggesting it is loud, powerful and a little frightening."},
      {title:"Personification", body:"“Load shedding stole our evening.”", answer:"Load shedding is given the human action of stealing — it emphasises the frustration and sense of loss."},
      {title:"Euphemism", body:"“Mr Khumalo passed away last night.”", answer:"<strong>Euphemism</strong> for “died”: it softens painful news and shows respect."},
    ],
    mistakes:["Calling every comparison a metaphor — check for like or as (simile).","Naming the device but not explaining its effect.","Confusing irony with coincidence or bad luck."],
    callout:{title:"How to answer", body:"Name the device → quote it → say what is compared or done → explain the effect on the reader. That pattern earns full marks."},
    activity:"Name the device: (a) “The wind whispered through the sugar cane.” (b) “I've told you a million times!” (c) “sizzling boerewors”",
    activityAnswer:"(a) Personification (b) Hyperbole (c) Onomatopoeia.",
    examTip:"“Identify” is usually 1 mark. “Discuss the effectiveness” wants the device, the comparison and the effect — at least two or three points.",
    keyterms:[{w:"Simile",d:"A comparison using like or as"},{w:"Metaphor",d:"A direct comparison: one thing is another"},{w:"Hyperbole",d:"Deliberate exaggeration for effect"}],
    quiz:[
      {q:"“Her smile was a sunrise” is a:",opts:["Simile","Metaphor","Onomatopoeia","Oxymoron"],a:1,et:"A direct comparison without like or as."},
      {q:"“Deafening silence” is an example of:",opts:["Oxymoron","Alliteration","Simile","Euphemism"],a:0,et:"Two opposite ideas side by side."},
      {q:"“Buzz”, “bang” and “sizzle” are examples of:",opts:["Personification","Hyperbole","Onomatopoeia","Irony"],a:2,et:"They imitate the sounds they describe."},
    ],
    conclusion:"Figurative language lets writers pack feeling into a few words. Spot it, then always explain what it does."},

  4: {emoji:"🔍", subtitle:"Grade 10–12 · Working out meaning from the words around it",
    illusText:"You don't need a dictionary for every new word — the sentence usually gives it away.",
    hook:{title:"The word you don't know", body:"A news article says: “The minister's promise was met with <strong>scepticism</strong> — residents have heard that load shedding would end ‘by December’ many times before.” Even if you've never seen the word, the rest of the sentence tells you: people <em>doubt</em> the promise. Using context like this is a skill Paper 1 tests directly."},
    intro:"<strong>Context clues</strong> include definitions, synonyms, contrasts (unlike, however, but) and examples. <strong>Word parts</strong> help too: prefixes (un-, mis-, pre-, re-), roots (bio = life, graph = write) and suffixes (-able, -less, -ology). <strong>Denotation</strong> is a word's dictionary meaning; <strong>connotation</strong> is the feeling it carries: <em>affordable</em> sounds positive, <em>cheap</em> may suggest poor quality. South African English also borrows words like <em>indaba</em>, <em>ubuntu</em>, <em>lekker</em> and <em>braai</em>.",
    concepts:[
      {t:"green", title:"🧭 Context clues", body:"Look before and after the word. A contrast word (unlike, but) tells you the meaning is the opposite of something nearby."},
      {t:"teal", title:"🧩 Word parts", body:"un + afford + able = cannot be afforded. Knowing 20 common prefixes and suffixes unlocks hundreds of words."},
      {t:"gold", title:"💬 Connotation", body:"Slim / skinny / scrawny all mean thin, but each carries a different attitude. Writers choose carefully — and so should you."},
    ],
    examples:[
      {title:"Contrast clue", body:"“Unlike his <u>gregarious</u> sister, who chats to everyone at the braai, Thabo is shy.”", answer:"<strong>Gregarious = sociable, outgoing.</strong> “Unlike” and “shy” signal the opposite meaning."},
      {title:"Word parts", body:"What does <em>unaffordable</em> mean?", answer:"un (not) + afford + able (can be) = <strong>cannot be afforded</strong>."},
      {title:"Connotation", body:"“The house is cheap” vs “The house is affordable”.", answer:"<em>Cheap</em> can suggest poor quality; <em>affordable</em> is positive — reasonably priced."},
    ],
    mistakes:["Giving a dictionary meaning that doesn't fit the sentence.","Ignoring connotation when asked why the writer chose a word.","Copying the whole sentence instead of giving the meaning."],
    callout:{title:"Test your answer", body:"Put your meaning back into the sentence in place of the word. If the sentence still makes sense, you're right."},
    activity:"What does <em>frugal</em> mean? “My gogo is <u>frugal</u>: she reuses bread bags, fixes old shoes and never wastes a cent.”",
    activityAnswer:"<strong>Careful and economical with money.</strong> The examples after the colon (reusing, fixing, not wasting) are the clue.",
    examTip:"When asked for a synonym, give one word or short phrase of the <strong>same part of speech</strong> — it must fit back into the sentence.",
    keyterms:[{w:"Context clue",d:"Information near a word that reveals its meaning"},{w:"Prefix",d:"A word part added to the start (un-, mis-, re-)"},{w:"Connotation",d:"The feelings or associations a word carries"}],
    quiz:[
      {q:"“The rain was <em>incessant</em> — it fell for five days without stopping.” Incessant means:",opts:["Light","Unending","Warm","Sudden"],a:1,et:"“Without stopping” is the clue."},
      {q:"The prefix <em>mis-</em> in “misunderstand” means:",opts:["Again","Wrongly","Before","Not enough"],a:1,et:"To understand wrongly."},
      {q:"Which word is most <strong>positive</strong> for someone careful with money?",opts:["Stingy","Cheap","Thrifty","Miserly"],a:2,et:"Thrifty has a positive connotation; the others are negative."},
    ],
    conclusion:"Every text is full of clues. Read around the word, break it into parts, and listen for its connotation."},

  5: {emoji:"🎙️", subtitle:"Grade 10–12 · The right voice for the right audience",
    illusText:"“cnt make it 2day lol” is fine for a friend — not for your principal.",
    hook:{title:"Texting the principal", body:"“Hey Mr Dlamini, cnt make it 2day lol 🙏” might work with a friend, but sent to your principal it sounds disrespectful. “Good morning, Mr Dlamini. Unfortunately I will not be able to attend today because I am ill.” says the same thing in the right <strong>register</strong>. Choosing your voice for your audience is a life skill — and an exam skill."},
    intro:"<strong>Register</strong> is the level of formality: formal, informal, colloquial or slang, and technical. It depends on <strong>audience</strong> (who reads it) and <strong>purpose</strong> (why it's written). <strong>Tone</strong> is the writer's attitude — sarcastic, sympathetic, urgent, nostalgic, humorous, critical. Tone is built through <strong>diction</strong> (word choice), punctuation and sentence length. <strong>Mood</strong> is different: it's the feeling the text creates in the reader.",
    concepts:[
      {t:"green", title:"👔 Formal vs informal", body:"Formal: full words, no contractions or slang, polite phrasing. Informal: contractions, everyday words, a friendly voice."},
      {t:"teal", title:"🎯 Diction carries tone", body:"“Wonderful, another outage” uses a positive word sarcastically. The tone comes from the gap between the word and the situation."},
      {t:"gold", title:"👥 Audience and purpose", body:"A complaint to the municipality, a speech at a friend's 18th and an online review all need different registers."},
    ],
    examples:[
      {title:"Make it formal", body:"“Yo, the soccer field is a mess — sort it out.”", answer:"<strong>The soccer field is in poor condition. Could it please be repaired?</strong>"},
      {title:"Name the tone", body:"“Oh wonderful, another ‘temporary’ water outage — the fourth this month.”", answer:"<strong>Sarcastic.</strong> “Wonderful” is used ironically and the inverted commas around ‘temporary’ mock the word."},
      {title:"Match the register", body:"A letter to the municipality vs a speech at your best friend's 18th.", answer:"Letter: <strong>formal</strong>. Speech: <strong>informal and warm</strong>, with humour and personal stories."},
    ],
    mistakes:["Using slang or SMS spelling in formal writing.","Describing tone as “good” or “bad” instead of naming it precisely.","Confusing tone (the writer's attitude) with mood (the reader's feeling)."],
    callout:{title:"Tone vocabulary", body:"Build a word bank: bitter, mocking, nostalgic, urgent, defiant, sympathetic, objective, light-hearted, condescending, hopeful."},
    activity:"Write the message “I will be late” twice: once to a friend and once to an employer.",
    activityAnswer:"Friend: “Running late, sorry! Be there in 15 😅” Employer: “Good morning. I apologise, but I will be about fifteen minutes late because of a delay on my route.”",
    examTip:"When asked about tone, name it in one precise word and quote the words that create it.",
    keyterms:[{w:"Register",d:"The level of formality in language"},{w:"Tone",d:"The writer's attitude towards the subject"},{w:"Diction",d:"The writer's choice of words"}],
    quiz:[
      {q:"Which is appropriate in a formal letter?",opts:["Hey guys!","I'm writing coz…","I am writing to request…","Sorry 4 the trouble"],a:2,et:"Full words, polite and clear."},
      {q:"The writer's attitude towards the subject is called:",opts:["Mood","Tone","Register","Plot"],a:1,et:"Mood is the reader's feeling; tone is the writer's attitude."},
      {q:"“Oh great, the bus is late again.” The tone is most likely:",opts:["Sincere","Sarcastic","Admiring","Neutral"],a:1,et:"“Great” is said with the opposite meaning."},
    ],
    conclusion:"Before you write, ask who will read it and why. That decides your register — and your tone follows."},
};

