LESSON_DB.english_hl.m1 = {
  0: {emoji:"📖", subtitle:"Grade 10–12 · Read the questions, then read with a purpose",
    illusText:"The marks in brackets tell you how much to write. Most learners ignore them.",
    hook:{title:"The contract nobody read", body:"Sipho signs a 24-month cellphone contract without reading it. Three months later his bill doubles: a clause on page 3 said out-of-bundle data costs extra. Reading carefully — knowing what to look for and where — protects you in real life. Comprehension in Paper 1 trains exactly that skill."},
    intro:"Good readers use a plan. <strong>Before</strong>: read the title, headings and the questions so you know what to look for. <strong>During</strong>: mark key words, names, numbers and the writer's opinion. <strong>After</strong>: answer in full sentences, using the mark allocation as a guide. Know the question verbs: <strong>identify</strong> (name it), <strong>explain</strong> (give reasons), <strong>quote</strong> (copy the exact words), <strong>in your own words</strong> (don't copy), <strong>discuss</strong> (give a view with support).",
    concepts:[
      {t:"green", title:"❓ Questions first", body:"Reading the questions first turns you into a detective — you read the passage already knowing what clues to find."},
      {t:"teal", title:"🔤 Question verbs", body:"“Quote” wants exact words in inverted commas. “In your own words” gets zero if you copy. “Explain” needs a reason, not just a fact."},
      {t:"gold", title:"🔢 Marks = points", body:"A (2)-mark question needs two points or one point well developed. A (1)-mark question needs one short answer, not a paragraph."},
    ],
    examples:[
      {title:"Two marks", body:"“Explain why the writer says the town is ‘dying’. (2)”", answer:"Give <strong>two</strong> reasons from the text, e.g. young people are leaving for the cities and the factory has closed."},
      {title:"Quote vs own words", body:"“Quote ONE word that shows the speaker is angry.” vs “In your own words, explain how she feels.”", answer:"First: copy one exact word in inverted commas. Second: rephrase — copying the text earns no marks."},
      {title:"True or false", body:"“The writer supports the new law. True or False? Give a reason.”", answer:"Both parts are needed: <strong>False</strong> + a reason or quotation that proves it."},
    ],
    mistakes:["Quoting when the question says “in your own words”.","Writing a paragraph for a 1-mark question and running out of time.","Answering from your own opinion instead of the text."],
    callout:{title:"Paper 1 at a glance", body:"Section A is comprehension; there is also a summary and language questions on visual texts and editing. Comprehension carries the most marks, so practise it regularly."},
    activity:"Read: “Cape Town's dams fell to about 20% in early 2018. Residents were limited to 50 litres per person per day, and many learned to shower in under two minutes.” Explain, in your own words, how residents responded to the shortage. (2)",
    activityAnswer:"They had to live on a very small daily amount of water, and many cut their showers down to a minute or two.",
    examTip:"Underline the key word in each question (why, how, which, quote) and check that your answer actually answers that word.",
    keyterms:[{w:"Mark allocation",d:"The number in brackets showing how many points are needed"},{w:"Quote",d:"Copy the exact words in inverted commas"},{w:"Own words",d:"Rephrase without copying the text"}],
    quiz:[
      {q:"A question worth (3) marks usually needs:",opts:["One word","Three points or a well-developed answer","A full essay","A quote only"],a:1,et:"Match your answer to the marks."},
      {q:"“In your own words” means you must:",opts:["Quote the text exactly","Rephrase without copying","Skip the question","Give your opinion only"],a:1,et:"Copied answers get no marks."},
      {q:"For a TRUE/FALSE question that asks for a reason, you should:",opts:["Write only True or False","Give the answer AND a reason from the text","Give a reason only","Copy the whole paragraph"],a:1,et:"Both the choice and the evidence earn marks."},
    ],
    conclusion:"Comprehension is a method, not luck: questions first, read with purpose, and let the marks guide your answer."},

  1: {emoji:"⚡", subtitle:"Grade 10–12 · Reading fast without missing what matters",
    illusText:"Skim for the big picture. Scan for the one detail you need.",
    hook:{title:"Finding your result", body:"Every January, matrics open the newspaper results list looking for their exam number. Nobody reads every number on every page — your eyes jump to your school and your number range. That's <strong>scanning</strong>. Reading a news article's headline and first lines to see what it's about is <strong>skimming</strong>. Both save time in the exam."},
    intro:"<strong>Skimming</strong> is reading quickly for the general idea (gist): read the title, headings, the first and last paragraphs, and the <strong>topic sentence</strong> (usually the first sentence) of each paragraph. <strong>Scanning</strong> is searching for specific information — a name, date, number or key word — without reading everything. The Paper 1 <strong>summary</strong> uses both: skim to understand, scan to find the points, then rewrite them in your own words.",
    concepts:[
      {t:"green", title:"🦅 Skim for gist", body:"Headline, subheadings, first sentence of each paragraph, conclusion. In 60 seconds you know what the text is about."},
      {t:"teal", title:"🔦 Scan for details", body:"Decide what the detail looks like first (a date has numbers, a name has a capital) — then let your eyes search for that shape."},
      {t:"gold", title:"📝 The summary", body:"Find exactly the number of points asked for (usually seven), write each as a full sentence in your own words, and stay within the word limit."},
    ],
    examples:[
      {title:"Skimming an article", body:"Where do you look to get the gist of a news report in under a minute?", answer:"The <strong>headline</strong>, subheadings, the <strong>first sentence of each paragraph</strong> and the final paragraph."},
      {title:"Scanning a timetable", body:"Find the first Gautrain from Park Station to Pretoria after 07:30.", answer:"Scan only the departure column for times starting with <strong>07:3</strong> or later — ignore everything else."},
      {title:"Topic sentence", body:"“Spaza shops are central to township life. They open late, sell small quantities and sometimes give credit.” Which sentence is the topic sentence?", answer:"The <strong>first</strong> — it states the main idea; the second gives supporting details."},
    ],
    mistakes:["Reading every word when you only need one fact.","Skimming exam questions that need careful reading.","Ignoring headings, captions and bold words, which carry key information."],
    callout:{title:"Summary checklist", body:"Seven points · full sentences · own words · no examples or repetition · within the word limit · word count written at the end."},
    activity:"Give the main idea in one sentence: “Spaza shops are part of township life. They sell bread, airtime and paraffin late at night when supermarkets are closed. Many are run from homes, and some offer credit to families they know.”",
    activityAnswer:"Spaza shops serve townships by selling everyday goods conveniently, often late at night and sometimes on credit.",
    examTip:"For the summary, list your seven points first, then rewrite them in fluent sentences. Count your words honestly — exceeding the limit costs marks.",
    keyterms:[{w:"Skimming",d:"Reading quickly for the general idea"},{w:"Scanning",d:"Searching quickly for a specific detail"},{w:"Topic sentence",d:"The sentence that states a paragraph's main idea"}],
    quiz:[
      {q:"Looking quickly for a specific date in a text is called:",opts:["Skimming","Scanning","Summarising","Inferring"],a:1,et:"Scanning finds specific details."},
      {q:"To skim an article you mainly read:",opts:["Every word carefully","Headings and topic sentences","Only the last word","The footnotes"],a:1,et:"They carry the main ideas."},
      {q:"The Home Language summary usually asks for:",opts:["3 points in 200 words","7 points in about 90 words","10 quotations","One paragraph of opinion"],a:1,et:"Seven points within about 90 words — check your paper's instructions."},
    ],
    conclusion:"Fast reading is smart reading: skim to understand, scan to find, and you'll have time left to check your answers."},

  2: {emoji:"🕵️", subtitle:"Grade 11–12 · Reading between the lines",
    illusText:"“K.” — one letter, and you already know your friend is annoyed.",
    hook:{title:"The one-letter reply", body:"You cancel plans and your friend replies: “K.” They didn't say they're annoyed, but you know. That's <strong>inference</strong> — working out what isn't stated from the clues that are. Writers rely on readers doing this all the time, and higher-order comprehension questions test it."},
    intro:"An <strong>inference</strong> is a conclusion based on <strong>evidence in the text</strong> plus <strong>your own knowledge</strong>. Analysis questions ask <em>why</em> the writer made a choice: why this word, this short sentence, this image? Critical questions ask about <strong>purpose</strong> (to inform, persuade, entertain), <strong>bias</strong> (one-sided views) and the writer's <strong>attitude</strong>. Every inference must be supported by evidence.",
    concepts:[
      {t:"green", title:"➕ Evidence + knowledge", body:"Slammed bag + silence at supper (evidence) + we know how upset people behave (knowledge) = she's angry (inference)."},
      {t:"teal", title:"✂️ The writer's choices", body:"Short sentences create tension. Repetition creates emphasis. Loaded words (“so-called”, “claims”) reveal attitude."},
      {t:"gold", title:"⚖️ Thinking critically", body:"Ask: Who wrote this? For whom? What do they want me to believe? Whose voice is missing?"},
    ],
    examples:[
      {title:"What do you infer?", body:"“Lindiwe slammed her bag on the table and didn't say a word at supper.”", answer:"She is <strong>upset or angry</strong> — slamming and silence are signs of anger."},
      {title:"Why a short sentence?", body:"After a long description of a quiet evening: “Then the lights went out.”", answer:"The short sentence creates <strong>suspense and a sudden shift</strong> — it stops the reader abruptly, like the darkness."},
      {title:"The writer's attitude", body:"“The so-called upgrade to the clinic consists of a new coat of paint.”", answer:"<strong>Critical and sarcastic</strong>: “so-called” suggests the upgrade isn't real, and “a new coat of paint” shows how little was done."},
    ],
    mistakes:["Giving an opinion with no evidence from the text.","Retelling what happened instead of explaining what it suggests.","Over-reading: inventing meanings the text doesn't support."],
    callout:{title:"A sentence frame that works", body:"“The writer says ___, which suggests ___ because ___.” Use it until it becomes automatic."},
    activity:"“The fridge was empty except for half a loaf of bread and a jar of achar. Mama counted the coins twice before leaving for the shop.” What can you infer about the family?",
    activityAnswer:"Money is tight: the nearly empty fridge and counting the coins twice suggest they can only afford a little.",
    examTip:"For “What does this suggest?” questions, always answer with the suggestion AND the evidence. The evidence is where most marks are lost.",
    keyterms:[{w:"Inference",d:"A conclusion drawn from evidence and reasoning"},{w:"Bias",d:"A one-sided view that favours a particular position"},{w:"Purpose",d:"Why a text was written: inform, persuade, entertain"}],
    quiz:[
      {q:"An inference is:",opts:["A fact stated directly","A conclusion from evidence and reasoning","A spelling rule","A type of poem"],a:1,et:"You work it out from clues."},
      {q:"“So-called” before a word usually signals:",opts:["Admiration","Doubt or sarcasm","Excitement","Agreement"],a:1,et:"It suggests the label isn't deserved."},
      {q:"A very short sentence after long ones often creates:",opts:["Confusion","Emphasis or suspense","A list","A question"],a:1,et:"The change in rhythm makes the reader pause."},
    ],
    conclusion:"Great readers ask what's <em>not</em> said. Find the clue, make the inference, prove it with evidence."},

  3: {emoji:"🖼️", subtitle:"Grade 10–12 · Advertisements, cartoons and infographics",
    illusText:"Every word, colour and face in an advert was chosen to make you want something.",
    hook:{title:"The billboard on the N1", body:"A huge billboard shows an ice-cold bottle dripping with water, a smiling group of friends at a braai and the words “Mzansi's Refreshment”. No one says “buy this”, yet everything — colour, faces, the word Mzansi — is designed to make you feel thirsty and part of the group. Paper 1 asks you to explain <strong>how</strong> visual texts persuade and amuse."},
    intro:"<strong>Advertisements</strong> have a target audience, a <strong>slogan</strong> (short memorable phrase), <strong>copy</strong> (the main text), images, a logo and often small print. Persuasive techniques include emotional appeal, bandwagon (everyone's doing it), celebrity endorsement, statistics and expert opinion, puns and rhetorical questions. <strong>Cartoons and comic strips</strong> use frames, speech and thought bubbles, facial expressions, body language and font to create humour or satire — Zapiro's political cartoons are a famous South African example.",
    concepts:[
      {t:"green", title:"📣 Persuasive techniques", body:"Bandwagon, emotional appeal, celebrity, statistics, exclusivity (“limited offer”), puns. Identify the technique and its effect on the target audience."},
      {t:"teal", title:"💬 Cartoon clues", body:"Jagged bubbles = shouting. Cloud bubbles = thinking. Sweat drops, wide eyes and raised eyebrows show emotion. Bold or large font shows emphasis."},
      {t:"gold", title:"🔗 Words + pictures", body:"The image and the words work together. The best answers explain how one supports or contrasts with the other."},
    ],
    examples:[
      {title:"Name the technique", body:"“Join 2 million South Africans who bank smarter.”", answer:"<strong>Bandwagon</strong>: it makes readers feel they'll be left out if they don't join."},
      {title:"Read the cartoon", body:"A character has sweat drops, wide eyes and a tiny speech bubble saying “Um…”.", answer:"The visual clues show <strong>nervousness or panic</strong>; the small bubble suggests a weak, hesitant voice."},
      {title:"Font choice", body:"Why is the word FREE much bigger than the rest of the advert?", answer:"To <strong>grab attention</strong> and emphasise the benefit — the reader notices the offer before the conditions."},
    ],
    mistakes:["Describing the picture without explaining its effect.","Ignoring the small print, which often contradicts the big promise.","Not linking the visual to the words."],
    callout:{title:"Critical eye", body:"Ask who the advert targets and what it leaves out. Small print like “Ts & Cs apply” often hides the real cost."},
    activity:"Find an advert on a taxi poster, in a magazine or online. Identify the target audience, the slogan and one persuasive technique, and explain its effect.",
    activityAnswer:"Example: a data-bundle advert targets teenagers; slogan “Stay connected”; technique: emotional appeal — images of friends laughing on video calls make you feel you'll miss out without data.",
    examTip:"For cartoon questions, always refer to a <strong>visual clue</strong> (expression, gesture, font, setting) as well as the words.",
    keyterms:[{w:"Slogan",d:"A short, memorable phrase in an advert"},{w:"Target audience",d:"The group a text is aimed at"},{w:"Satire",d:"Humour used to criticise people or society"}],
    quiz:[
      {q:"“9 out of 10 dentists recommend…” uses:",opts:["Bandwagon only","Statistics and expert appeal","Onomatopoeia","Euphemism"],a:1,et:"It uses numbers and experts to sound trustworthy."},
      {q:"In a comic strip, a jagged speech bubble usually shows:",opts:["Whispering","Shouting or a loud sound","Thinking","A flashback"],a:1,et:"Jagged edges suggest volume or shock."},
      {q:"The short memorable phrase in an advert is the:",opts:["Copy","Slogan","Logo","Caption"],a:1,et:"For example “Mzansi's Refreshment”."},
    ],
    conclusion:"Visual texts persuade fast. Slow them down: name the technique, find the visual clue, explain the effect."},

  4: {emoji:"⚖️", subtitle:"Grade 11–12 · Same event, different angles",
    illusText:"Two headlines, one taxi strike — and two completely different stories.",
    hook:{title:"Two headlines, one strike", body:"Paper A: “Taxi strike leaves thousands of commuters stranded.” Paper B: “Taxi drivers fight for fair permits.” Same day, same event. One focuses on the inconvenience to commuters; the other sympathises with drivers. Comparing texts teaches you to notice <strong>whose story</strong> is being told."},
    intro:"When you compare texts, look at <strong>purpose</strong> (inform, persuade, entertain), <strong>audience</strong>, <strong>tone</strong>, <strong>register</strong>, <strong>point of view</strong>, <strong>bias</strong> and <strong>format</strong> (news report, poster, blog, speech). Use comparative connectors — <em>whereas</em>, <em>similarly</em>, <em>in contrast</em>, <em>both</em> — and always refer to both texts.",
    concepts:[
      {t:"green", title:"👁️ Point of view and bias", body:"Which people are quoted? Which facts are included or left out? Loaded words reveal which side the writer favours."},
      {t:"teal", title:"📰 Purpose and format", body:"A poster persuades in a few words; a report informs in detail. Format choices follow purpose."},
      {t:"gold", title:"🔀 Comparison language", body:"“Text A … whereas Text B …” in one sentence shows the marker you're comparing, not just describing."},
    ],
    examples:[
      {title:"Compare the headlines", body:"“Taxi strike leaves commuters stranded” vs “Taxi drivers fight for fair permits”.", answer:"Headline A focuses on <strong>commuters' hardship</strong>, whereas headline B presents the <strong>drivers' grievance</strong> sympathetically."},
      {title:"Poster vs report", body:"An anti-bullying poster and a news report about the same campaign.", answer:"The poster is <strong>persuasive, brief and visual</strong>; the report is <strong>informative and detailed</strong>, with facts and quotations."},
      {title:"Which is more objective?", body:"Text A quotes residents, the council and police. Text B quotes one angry resident.", answer:"<strong>Text A</strong> — it gives several viewpoints, while Text B presents only one side."},
    ],
    mistakes:["Discussing only one text.","Listing differences without explaining their effect.","Calling one text “better” without saying why."],
    callout:{title:"Real life", body:"Comparing sources is how you spot fake news: check who else is reporting the story and what they include or leave out."},
    activity:"Text A: “The new mall brings 800 jobs to Soshanguve.” Text B: “Local spaza owners fear the new mall will shut them down.” Compare the viewpoints.",
    activityAnswer:"Text A presents the mall positively, focusing on job creation, whereas Text B focuses on the threat to small local businesses. A celebrates; B warns.",
    examTip:"Answer comparison questions with both texts in the same sentence — “Text A …, whereas Text B …” — to earn full marks.",
    keyterms:[{w:"Bias",d:"Favouring one side unfairly"},{w:"Objective",d:"Balanced and based on facts"},{w:"Point of view",d:"The perspective from which a text is written"}],
    quiz:[
      {q:"Which word signals contrast?",opts:["Similarly","Whereas","Also","Likewise"],a:1,et:"Whereas introduces a difference."},
      {q:"A text that presents only one side of an argument shows:",opts:["Balance","Bias","Objectivity","Register"],a:1,et:"One-sidedness is bias."},
      {q:"When comparing two texts, you should:",opts:["Discuss only the first","Refer to both texts","Give only your opinion","Copy both texts"],a:1,et:"Comparison needs both."},
    ],
    conclusion:"Every text chooses an angle. Compare them side by side and you'll see whose story is being told — and whose isn't."},

  5: {emoji:"🎬", subtitle:"Grade 10–12 · How writers build meaning in stories, poems and plays",
    illusText:"When a character pockets a knife in episode one, you already know it will matter.",
    hook:{title:"The knife in episode one", body:"In the first episode of a series, a character slips a knife into a drawer. The camera lingers on it. You just <em>know</em> it will come back. That's <strong>foreshadowing</strong>. Writers of novels, plays and short stories use the same tools as scriptwriters — and Paper 2 asks you to spot them and explain why they're used."},
    intro:"<strong>Structure devices</strong>: foreshadowing (hints of what's to come), flashback (a scene from the past), suspense and cliffhangers. <strong>Irony</strong>: dramatic irony (the audience knows more than the character), situational irony (the opposite of what's expected happens), verbal irony (saying the opposite of what you mean). <strong>Meaning devices</strong>: symbol (an object standing for an idea), motif (a repeated image or idea), imagery, setting, pathetic fallacy (weather reflecting feelings). <strong>Narration</strong>: first person (I) or third person (he/she), and whether the narrator can be trusted.",
    concepts:[
      {t:"green", title:"🧭 Structure", body:"Foreshadowing builds anticipation; flashback explains the present by showing the past."},
      {t:"teal", title:"🕯️ Symbol, motif, theme", body:"A symbol stands for something bigger. A motif keeps returning. A <strong>theme</strong> is the message — written as a full sentence, not one word."},
      {t:"gold", title:"🗣️ Narrator", body:"A first-person narrator gives intimacy but limited knowledge; a third-person omniscient narrator knows everyone's thoughts."},
    ],
    examples:[
      {title:"Name the device", body:"Thunder rumbles as two brothers start arguing in the opening scene.", answer:"<strong>Pathetic fallacy</strong> and <strong>foreshadowing</strong>: the storm reflects their anger and hints at worse conflict."},
      {title:"Symbol and motif", body:"A candle burns lower in each chapter as an old man grows weaker.", answer:"The candle is a <strong>symbol</strong> of his life fading; its repetition makes it a <strong>motif</strong>."},
      {title:"Irony", body:"The reader knows the letter was never delivered, but the character waits every day for a reply.", answer:"<strong>Dramatic irony</strong>: we know something the character doesn't, which creates sympathy and tension."},
    ],
    mistakes:["Writing a theme as one word (“love”) instead of a statement.","Retelling the plot instead of analysing the device.","Mixing up dramatic irony and situational irony."],
    callout:{title:"Theme as a sentence", body:"Not “greed” but “Greed destroys relationships and leaves people isolated.” A full-sentence theme gives you something to argue in an essay."},
    activity:"Name the device: “Years earlier, as a boy in Alexandra, he had sworn he would never return.”",
    activityAnswer:"<strong>Flashback</strong> — the narrative moves back to an earlier time.",
    examTip:"Never just name a device: explain what it does for the reader or the story's meaning.",
    keyterms:[{w:"Foreshadowing",d:"A hint of events to come"},{w:"Dramatic irony",d:"The audience knows something a character doesn't"},{w:"Theme",d:"The central message of a text, stated as a sentence"}],
    quiz:[
      {q:"A hint about what will happen later is:",opts:["Flashback","Foreshadowing","Hyperbole","Pun"],a:1,et:"It prepares the reader for future events."},
      {q:"When the audience knows something a character does not, it is:",opts:["Dramatic irony","Alliteration","Simile","Flashback"],a:0,et:"It creates tension and sympathy."},
      {q:"Weather that reflects characters' feelings is:",opts:["Pathetic fallacy","Oxymoron","Euphemism","Onomatopoeia"],a:0,et:"Nature mirrors human emotion."},
    ],
    conclusion:"Writers build stories with tools you already recognise from films. Name the tool, then explain what it builds."},
};

// ─── Module 2: Writing Skills ───────────────────────────────────────────────
LESSON_DB.english_hl.m2 = {
  0: {emoji:"🗣️", subtitle:"Grade 10–12 · Take a side and prove it",
    illusText:"Phones in class: yes or no? Pick a side — then make the marker believe you.",
    hook:{title:"Phones in class?", body:"Your school is debating whether learners may use phones in class. Some say phones distract; others say they're the cheapest way to look things up, especially where there's no library. Everyone has an opinion — but an <strong>argumentative essay</strong> turns opinion into a case: a clear stand, solid reasons and evidence, and a fair answer to the other side."},
    intro:"An <strong>argumentative essay</strong> takes one clear position and defends it. The introduction ends with a <strong>thesis statement</strong> (your stand plus your main reasons). Each body paragraph makes one point using <strong>PEEL</strong>: Point, Evidence (fact, example, statistic), Explanation, Link back to the thesis. A strong essay also includes a <strong>rebuttal</strong>: it states the opposing view and shows why it's weaker. A <strong>discursive essay</strong> is different — it presents both sides fairly before reaching a balanced conclusion. In Grade 12 Home Language, essays are usually <strong>400–450 words</strong>.",
    concepts:[
      {t:"green", title:"🎯 The thesis", body:"One sentence that states your position and previews your reasons. Every paragraph must support it."},
      {t:"teal", title:"🧱 PEEL paragraphs", body:"Point → Evidence → Explain → Link. One idea per paragraph, developed fully, beats five half-ideas."},
      {t:"gold", title:"🛡️ The rebuttal", body:"“Some argue…; however…” shows you've considered the other side — and makes your argument stronger, not weaker."},
    ],
    examples:[
      {title:"A thesis statement", body:"Topic: “Should school uniforms be scrapped?”", answer:"“School uniforms should stay because they reduce peer pressure, save families money and build school pride.”"},
      {title:"A PEEL paragraph", body:"Point: uniforms save money.", answer:"<strong>P:</strong> Uniforms save families money. <strong>E:</strong> One set worn five days a week costs far less than a wardrobe of brand-name clothes. <strong>E:</strong> Parents aren't pressured to buy expensive outfits for school. <strong>L:</strong> This is why uniforms make schools fairer for every learner."},
      {title:"A rebuttal", body:"Opposing view: uniforms are expensive.", answer:"“Some argue that uniforms are expensive; however, a uniform bought once a year still costs less than the constant pressure to buy fashionable clothes.”"},
    ],
    mistakes:["Sitting on the fence in an argumentative essay.","Making claims with no evidence or examples.","Using emotional ranting or slang instead of reasoned, formal language."],
    callout:{title:"Argumentative vs discursive", body:"Argumentative: pick a side and defend it. Discursive: weigh both sides fairly. Read the topic carefully — the wrong type loses marks."},
    activity:"Write a thesis statement and three reasons for: “Learners should do community service before they write matric.”",
    activityAnswer:"Example: “Community service before matric builds responsibility, gives learners real work experience and strengthens the communities they live in.”",
    examTip:"Spend five minutes planning: choose your side, list three points with evidence, then write. Markers reward a clear stand and logical structure.",
    keyterms:[{w:"Thesis statement",d:"A sentence stating your position and main reasons"},{w:"Rebuttal",d:"Answering and weakening the opposing view"},{w:"Discursive essay",d:"An essay that presents both sides fairly"}],
    quiz:[
      {q:"An argumentative essay must:",opts:["Present both sides equally","Take a clear stand","Tell a story","Describe a place"],a:1,et:"It defends one position."},
      {q:"Stating the opposing view and showing why it's weaker is a:",opts:["Rebuttal","Simile","Flashback","Summary"],a:0,et:"It strengthens your argument."},
      {q:"A discursive essay:",opts:["Takes one side only","Presents both sides fairly","Is a letter","Is a poem"],a:1,et:"It weighs both sides before concluding."},
    ],
    conclusion:"A good argument is a clear stand plus proof. Plan your thesis, build PEEL paragraphs, and answer the other side."},

  1: {emoji:"🌅", subtitle:"Grade 10–12 · Telling a story and painting a picture",
    illusText:"“It was hot” tells. “The tar was soft enough to hold my footprints” shows.",
    hook:{title:"Show, don't tell", body:"“It was hot” tells the reader. “The tar outside the taxi rank was so soft it held my footprints, and the vendor's ice lollies melted before anyone could buy them” <strong>shows</strong> it. Readers believe what they can see, hear and feel. That's the secret of narrative and descriptive writing."},
    intro:"A <strong>narrative essay</strong> tells a story: exposition (setting and characters), rising action, <strong>climax</strong> (the moment of highest tension), falling action and resolution. It needs a conflict, believable characters and a consistent point of view and tense. A <strong>descriptive essay</strong> creates a vivid picture of a person, place or moment, using the <strong>five senses</strong> and figurative language — it has little or no plot. Both rely on <strong>showing</strong> through specific details rather than telling.",
    concepts:[
      {t:"green", title:"📈 The plot arc", body:"Start close to the action, build tension, reach a clear climax, then resolve. One strong event beats ten rushed ones."},
      {t:"teal", title:"👀 Show, don't tell", body:"Replace emotion words with actions and details: not “she was nervous” but “her pen tapped the desk until the invigilator glared at her”."},
      {t:"gold", title:"👂 Five senses", body:"Sight, sound, smell, taste, touch. A taxi rank at dawn: hooting, diesel fumes, vetkoek frying, cold steel railings."},
    ],
    examples:[
      {title:"Show, don't tell", body:"Rewrite: “She was nervous.”", answer:"“Her pen tapped against the desk until the invigilator glared at her, and she realised she had read the first question four times.”"},
      {title:"An opening hook", body:"Start a story about a soccer final.", answer:"“The lights went off at exactly the moment Thabo stepped up to take the penalty.” — it starts in the action and creates suspense."},
      {title:"Using senses", body:"Describe a taxi rank at 6 a.m. in one sentence.", answer:"“Hooters blared over the hiss of frying vetkoek, and the sharp smell of diesel clung to the cold morning air.” — sound, smell, touch."},
    ],
    mistakes:["Too many events and no clear climax.","“And then… and then…” storytelling.","Ending with “it was all a dream”, and switching between past and present tense."],
    callout:{title:"Dialogue rules", body:"New speaker, new line. Punctuation goes inside the inverted commas: “Are you coming?” she asked. Use dialogue to reveal character, not to fill space."},
    activity:"Describe your kitchen at supper time in five sentences, using at least four senses.",
    activityAnswer:"Sample: “Steam fogged the window above the stove. Oil crackled as Mama dropped onions into the pot. The smell of curry pulled everyone from the lounge. The plates were still warm from the drying rack. I sneaked a taste of the gravy and burned my tongue.”",
    examTip:"Choose one tense (usually past) and stay in it. Read your story once just to check tense — it's the most common narrative error.",
    keyterms:[{w:"Climax",d:"The point of highest tension in a story"},{w:"Imagery",d:"Language that appeals to the senses"},{w:"Point of view",d:"Who tells the story: first or third person"}],
    quiz:[
      {q:"“Show, don't tell” means:",opts:["Use pictures","Reveal feelings through actions and details","Write only dialogue","Avoid adjectives"],a:1,et:"Details let readers feel it themselves."},
      {q:"The turning point of highest tension in a story is the:",opts:["Exposition","Climax","Resolution","Setting"],a:1,et:"Everything builds towards it."},
      {q:"A descriptive essay mainly relies on:",opts:["Statistics","Sensory details","Arguments","Bullet points"],a:1,et:"It paints a picture."},
    ],
    conclusion:"Stories live in details. Start in the action, show instead of tell, and let the senses do the work."},

  2: {emoji:"📨", subtitle:"Grade 10–12 · Transactional writing that gets results",
    illusText:"A burst pipe has flooded the street for two weeks. A well-written letter gets it fixed.",
    hook:{title:"The burst pipe", body:"A water pipe has been leaking in your street for two weeks, wasting water and flooding driveways. An angry social media post might get likes, but a clear, polite, well-formatted <strong>letter to the municipality</strong> creates a record and gets action. Transactional writing — letters, reports, CVs, speeches, emails — is the writing you'll do for the rest of your life."},
    intro:"A <strong>formal letter</strong> includes: the sender's address (top right), the date, the recipient's title and address (left), a salutation (<em>Dear Sir/Madam</em> or <em>Dear Mr Naidoo</em>), a <strong>subject line</strong>, a body with clear paragraphs (purpose → details → request), a closing (<em>Yours faithfully</em> after Sir/Madam; <em>Yours sincerely</em> after a name), signature and name. A <strong>report</strong> has a heading, introduction or terms of reference, findings, conclusions and <strong>recommendations</strong>. In Grade 12 Home Language, longer transactional texts are usually <strong>180–200 words</strong> and shorter ones <strong>100–120 words</strong>.",
    concepts:[
      {t:"green", title:"📐 Format first", body:"Correct layout earns easy marks and makes you look professional. Learn it once, use it forever."},
      {t:"teal", title:"✍️ Faithfully or sincerely?", body:"Dear Sir/Madam → Yours faithfully. Dear Ms Mokoena → Yours sincerely."},
      {t:"gold", title:"📊 Report structure", body:"Headings, numbered findings and practical recommendations. Objective language — facts, not feelings."},
    ],
    examples:[
      {title:"Subject line", body:"Letter to the municipality about the leak.", answer:"<strong>RE: BURST WATER PIPE IN MKHIZE STREET, KWAMASHU</strong> — specific and immediately clear."},
      {title:"Opening paragraph", body:"Start the body of the letter.", answer:"“I am writing to report a burst water pipe in Mkhize Street, which has been leaking for two weeks and is now flooding several driveways.”"},
      {title:"Match the closing", body:"The letter begins “Dear Mr Naidoo”.", answer:"<strong>Yours sincerely</strong> — because you used his name."},
    ],
    mistakes:["Informal language, slang or contractions (can't, won't) in formal letters.","The wrong closing for the salutation.","No subject line, or an emotional rant instead of clear facts and a request."],
    callout:{title:"Beyond the exam", body:"Job applications, bursary motivations, complaints to service providers and CVs all use these formats. This lesson pays off for life."},
    activity:"Write the subject line and opening paragraph of a letter applying for a weekend job at a local pharmacy.",
    activityAnswer:"Example: “RE: APPLICATION FOR WEEKEND SHOP ASSISTANT POSITION” — “I wish to apply for the weekend shop assistant position advertised in your store window. I am a reliable Grade 11 learner with good communication skills and a keen interest in healthcare.”",
    examTip:"Get the format right first — it's the easiest marks on the paper. Then keep the body focused: purpose, details, request.",
    keyterms:[{w:"Salutation",d:"The greeting: Dear Sir/Madam, Dear Mr Naidoo"},{w:"Subject line",d:"A short heading stating what the letter is about"},{w:"Recommendation",d:"A suggested action at the end of a report"}],
    quiz:[
      {q:"If you start “Dear Sir/Madam”, you end with:",opts:["Yours sincerely","Yours faithfully","Love","Cheers"],a:1,et:"Faithfully when the person isn't named."},
      {q:"A report usually ends with:",opts:["A cliffhanger","Recommendations","A poem","A greeting"],a:1,et:"Reports suggest what should be done."},
      {q:"Which is suitable in a formal letter?",opts:["I can't wait!!!","I would appreciate your urgent attention.","Thanks a mil","Hey there"],a:1,et:"Polite, formal and clear."},
    ],
    conclusion:"Format earns trust; clarity earns action. Master the layout and say exactly what you need."},

  3: {emoji:"🔎", subtitle:"Grade 10–12 · Finding and fixing errors",
    illusText:"“Learners must where there uniforms” — two errors in five words, on the school gate.",
    hook:{title:"The school notice", body:"A notice on the school gate reads: “All learners must where there uniforms on Friday.” Two errors in one short sentence — and every parent who walks past notices. <strong>Editing and proofreading</strong> is the difference between writing that looks careless and writing that earns respect."},
    intro:"<strong>Editing</strong> checks content and structure: does it make sense, flow logically and stay on topic? <strong>Proofreading</strong> checks surface errors: spelling, punctuation, capital letters, tense and <strong>concord</strong> (subject–verb agreement). Common errors include wrong concord (“one of the learners were”), tense shifts, unclear pronouns, <strong>redundancy</strong> or tautology (“free gift”, “return back”), and commonly confused words (where/wear, there/their).",
    concepts:[
      {t:"green", title:"🤝 Concord", body:"The verb agrees with the real subject: “One of the learners <strong>was</strong> late” — the subject is <em>one</em>, not <em>learners</em>."},
      {t:"teal", title:"⏳ Tense consistency", body:"If your story is in the past tense, every action stays in the past unless there's a reason to shift."},
      {t:"gold", title:"✂️ Cut redundancy", body:"Free gift, return back, past history, final outcome — the extra word adds nothing. Cut it."},
    ],
    examples:[
      {title:"Concord", body:"“One of the learners were late.”", answer:"<strong>One of the learners was late.</strong> The subject is “one”."},
      {title:"Redundancy", body:"“Please return back the forms.”", answer:"<strong>Please return the forms.</strong> “Return” already means “give back”."},
      {title:"Tense", body:"“Yesterday I go to the clinic and wait for three hours.”", answer:"<strong>Yesterday I went to the clinic and waited for three hours.</strong>"},
    ],
    mistakes:["“The list of items are…” (the list is).","“Each of the boys have…” (each has).","“Me and him went…” (He and I went)."],
    callout:{title:"How to proofread", body:"Read slowly, aloud if you can, one sentence at a time. Check one thing per pass: first spelling, then punctuation, then concord and tense."},
    activity:"Correct: “Neither of the boys have finished there homework, and the teacher are angry.”",
    activityAnswer:"<strong>Neither of the boys has finished his homework, and the teacher is angry.</strong> (Neither → has; there → his; teacher → is.)",
    examTip:"Leave five minutes at the end of every writing question to proofread. Language errors are penalised in every rubric.",
    keyterms:[{w:"Concord",d:"Agreement between subject and verb"},{w:"Tautology",d:"Saying the same thing twice in different words"},{w:"Proofreading",d:"Checking for surface errors"}],
    quiz:[
      {q:"Which is correct?",opts:["The list of names are long.","The list of names is long.","The list of names be long.","The lists of names is long."],a:1,et:"The subject is “list” (singular)."},
      {q:"“Free gift” is an example of:",opts:["Tautology/redundancy","Alliteration","Concord","Simile"],a:0,et:"A gift is already free."},
      {q:"Choose the correct form: “Each of the players ___ a medal.”",opts:["receive","receives","are receiving","have received"],a:1,et:"“Each” is singular."},
    ],
    conclusion:"Clean writing is careful writing. Proofread in passes and the easy marks stay yours."},

  4: {emoji:"🎤", subtitle:"Grade 11–12 · Making your writing sound like you — on purpose",
    illusText:"“Never, never and never again…” — three words that a nation remembers.",
    hook:{title:"Never, never and never again", body:"At his inauguration in 1994, Nelson Mandela said: “Never, never and never again shall it be that this beautiful land will again experience the oppression of one by another.” The repetition makes it unforgettable. <strong>Style</strong> — the way words are chosen and arranged — is what makes writing memorable."},
    intro:"<strong>Style</strong> is built from diction (word choice), sentence variety (short and long, simple and complex), figurative language and <strong>rhetorical devices</strong>: repetition, the rule of three, rhetorical questions, direct address (“Fellow learners…”), contrast and emotive language. Your tone should match your purpose: a farewell speech can be warm and humorous; a report to the SGB should be objective and concise.",
    concepts:[
      {t:"green", title:"📏 Sentence variety", body:"A long, flowing sentence followed by a short one creates emphasis. Like this."},
      {t:"teal", title:"🎯 Rhetorical devices", body:"Rule of three (“learn, grow, lead”), rhetorical questions and repetition make speeches and arguments powerful."},
      {t:"gold", title:"🧠 Diction", body:"Choose precise words over fancy ones. “Exhausted” beats “very very tired”; “walked” beats “perambulated”."},
    ],
    examples:[
      {title:"Name the device", body:"“Never, never and never again…”", answer:"<strong>Repetition</strong> (and the rule of three) — it emphasises how determined the speaker is."},
      {title:"Rhetorical question", body:"Write one for a speech about school transport.", answer:"“How many more learners must walk ten kilometres to school before something changes?”"},
      {title:"Vary the rhythm", body:"“We trained hard. We trained every day. We trained in the rain.”", answer:"Repetition builds intensity; adding a short final sentence — “We won.” — creates a powerful ending."},
    ],
    mistakes:["Using big words to sound clever (thesaurus abuse).","Clichés like “at the end of the day” and “every cloud has a silver lining”.","Every sentence the same length and pattern."],
    callout:{title:"Speech writing", body:"Open with a hook, address your audience directly, use the rule of three, and end with a line people will remember."},
    activity:"Rewrite this flat sentence using a rhetorical device: “We should recycle more.”",
    activityAnswer:"Examples: “If not us, who? If not now, when?” or “Reduce, reuse, recycle — it's not a slogan, it's a responsibility.”",
    examTip:"In a speech, use direct address (“Fellow learners”, “Honoured guests”), a strong opening and a memorable final line.",
    keyterms:[{w:"Style",d:"The way a writer chooses and arranges words"},{w:"Rhetorical question",d:"A question asked for effect, not for an answer"},{w:"Cliché",d:"An overused phrase that has lost its impact"}],
    quiz:[
      {q:"“Never, never and never again” uses:",opts:["Repetition","Euphemism","Onomatopoeia","Oxymoron"],a:0,et:"Repeating words for emphasis."},
      {q:"A question asked for effect, not for an answer, is a:",opts:["Rhetorical question","Direct question","Reported question","Interjection"],a:0,et:"It makes the audience think."},
      {q:"Phrases like “at the end of the day” are:",opts:["Clichés","Technical terms","Neologisms","Euphemisms"],a:0,et:"Overused and stale."},
    ],
    conclusion:"Style is a choice. Vary your sentences, pick precise words and use rhetorical devices with purpose."},

  5: {emoji:"⏱️", subtitle:"Grade 12 · Planning, timing and finishing Paper 3",
    illusText:"A brilliant essay doesn't help if you never reach the last question.",
    hook:{title:"The unfinished paper", body:"Two learners write the same writing paper. One produces a brilliant essay but runs out of time and leaves the last question blank. The other writes a good essay, a solid letter and a complete short text. The second learner scores higher. <strong>Exam technique</strong> — timing, planning and checking — turns ability into marks."},
    intro:"The Home Language writing paper (Paper 3) is usually <strong>100 marks in 2½ hours</strong>: an essay (50), a longer transactional text (30) and a shorter transactional text (20). That's about <strong>1.5 minutes per mark</strong>. For every question: read the topic carefully, <strong>plan</strong> (the paper expects you to show planning), write a draft or careful final version, then edit. Check your paper's instructions for word counts and whether to include a title.",
    concepts:[
      {t:"green", title:"⏰ Time by marks", body:"About 75 minutes for the essay, 45 for the longer text, 30 for the shorter one — including planning and checking."},
      {t:"teal", title:"🗺️ Plan → write → edit", body:"A quick mind map or list of points saves time and keeps your writing on topic."},
      {t:"gold", title:"🎯 Answer the topic", body:"Underline the key instruction word (describe, argue, narrate, reflect) and the format required."},
    ],
    examples:[
      {title:"Time calculation", body:"150 minutes for 100 marks. How long for the 50-mark essay?", answer:"150 ÷ 100 = 1.5 min per mark → 50 × 1.5 = <strong>75 minutes</strong>."},
      {title:"Choosing a topic", body:"How do you pick your essay topic quickly?", answer:"Choose the topic where you can immediately list <strong>three strong ideas or a clear story</strong> — not the one that just sounds impressive."},
      {title:"Read the instruction", body:"Topic: “Describe a place that holds special memories.”", answer:"Write a <strong>descriptive</strong> essay full of sensory detail — not a story with a plot twist or an argument."},
    ],
    mistakes:["Spending most of the time on the essay and rushing or skipping the short texts.","Misreading the topic type (describe vs narrate vs argue).","No paragraphs, or no time left to proofread."],
    callout:{title:"Your game plan", body:"Read all questions first (5 min) → essay (75 min) → longer text (40 min) → shorter text (25 min) → final check (5 min)."},
    activity:"Make your own time plan for a 2½-hour, 100-mark writing paper, including planning and checking time for each section.",
    activityAnswer:"Example: Reading 5 min; essay 70 min (plan 10, write 50, check 10); longer text 42 min; shorter text 28 min; final check 5 min = 150 min.",
    examTip:"Put a watch on your desk and write your finish times next to each question before you start.",
    keyterms:[{w:"Mark allocation",d:"How many marks a question is worth"},{w:"Planning",d:"Organising ideas before writing"},{w:"Transactional text",d:"Practical writing such as letters, reports and speeches"}],
    quiz:[
      {q:"With 150 minutes for 100 marks, a 30-mark question gets about:",opts:["20 minutes","30 minutes","45 minutes","60 minutes"],a:2,et:"30 × 1.5 = 45 minutes."},
      {q:"Before drafting an essay you should:",opts:["Start writing immediately","Plan your ideas","Write only the conclusion","Count your words"],a:1,et:"Planning keeps you on topic."},
      {q:"If the topic says “Describe”, you should write:",opts:["A story with a twist","A descriptive essay with sensory detail","An argument","A letter"],a:1,et:"Follow the instruction word."},
    ],
    conclusion:"Marks come from finishing well, not just starting well. Time it, plan it, check it."},
};

// ─── Module 3: Literature ───────────────────────────────────────────────────
LESSON_DB.english_hl.m3 = {
  0: {emoji:"📚", subtitle:"Grade 10–12 · Reading a novel like an examiner",
    illusText:"A father travels from Ndotsheni to Johannesburg to find his son — and finds a country.",
    hook:{title:"A father's journey", body:"In Alan Paton's <em>Cry, the Beloved Country</em> (1948), the Reverend Stephen Kumalo leaves his village of Ndotsheni in KwaZulu-Natal to search for his son Absalom in Johannesburg. What starts as a family search becomes a portrait of a divided country. A novel works on two levels — a story about people, and a message about life. Studying a novel means tracking both."},
    intro:"Key elements: <strong>plot</strong>, <strong>setting</strong> (time, place and social context), <strong>characters</strong> (protagonist, antagonist; round or flat; dynamic or static), <strong>conflict</strong> (internal or external), <strong>narrator</strong>, <strong>style</strong> and <strong>themes</strong>. In Paper 2 you answer either a literary essay (usually about 400–450 words in Home Language) or contextual questions on extracts. Keep a reading log: for each character and theme, note key events and short quotations with chapter references.",
    concepts:[
      {t:"green", title:"👤 Character arcs", body:"Does the character change (dynamic) or stay the same (static)? What causes the change? That's often where the theme lives."},
      {t:"teal", title:"🌍 Setting with purpose", body:"Setting isn't just background. Contrasting places — village and city, rich and poor — often carry the novel's message."},
      {t:"gold", title:"💡 Theme with evidence", body:"State the theme as a sentence and support it with two or three moments from the novel."},
    ],
    examples:[
      {title:"Protagonist", body:"Who is the protagonist of <em>Cry, the Beloved Country</em>?", answer:"<strong>Stephen Kumalo</strong> — the story follows his journey, choices and growth."},
      {title:"Setting as meaning", body:"How do Ndotsheni and Johannesburg contrast?", answer:"Ndotsheni is a struggling rural community whose land is failing; Johannesburg draws people in and breaks families apart. The contrast shows how social change damaged communities."},
      {title:"A theme statement", body:"Turn “fear” into a theme statement.", answer:"“Fear and injustice divide people, but compassion and forgiveness can begin to heal them.”"},
    ],
    mistakes:["Retelling the plot instead of analysing it.","Relying only on summaries — markers can tell.","Making claims without quotations or specific references."],
    callout:{title:"Reading log", body:"One page per main character and per theme. Add a quotation and chapter number every time something important happens. By exam time, your notes are your study guide."},
    activity:"Start a character log for your set novel: name, three key events, one quotation and how the character changes.",
    activityAnswer:"Answers depend on the novel. Check that each entry has an event, a short quotation with its chapter and a comment on what it reveals.",
    examTip:"In a literary essay, every paragraph needs a point about the topic, evidence from the text and an explanation that links back to the question.",
    keyterms:[{w:"Protagonist",d:"The main character"},{w:"Dynamic character",d:"A character who changes during the story"},{w:"Internal conflict",d:"A struggle within a character's mind"}],
    quiz:[
      {q:"The main character in a novel is the:",opts:["Antagonist","Protagonist","Narrator, always","Foil"],a:1,et:"The protagonist drives the story."},
      {q:"A character who changes during the story is:",opts:["Static","Dynamic","Flat","Minor"],a:1,et:"Dynamic means changing."},
      {q:"A struggle within a character's mind is:",opts:["External conflict","Internal conflict","Setting","Climax"],a:1,et:"For example guilt or a difficult choice."},
    ],
    conclusion:"Read for the story, study for the meaning. Characters, setting and conflict all point to the theme."},

  1: {emoji:"🎭", subtitle:"Grade 10–12 · Reading a play as a performance",
    illusText:"“To be, or not to be” — a voice note to yourself at 2 a.m., written 400 years ago.",
    hook:{title:"A 400-year-old voice note", body:"Hamlet stands alone on stage and says, “To be, or not to be: that is the question.” He's thinking aloud about life, death and whether to act — like recording a voice note to yourself at 2 a.m. That speech is a <strong>soliloquy</strong>, and it's one of the tools that makes drama different from a novel: we see characters speak and act, not just read about them."},
    intro:"A play is written to be performed. Key features: <strong>acts and scenes</strong>, <strong>stage directions</strong> (how actors move and speak), <strong>dialogue</strong>, <strong>monologue</strong>, <strong>soliloquy</strong> (a character alone, revealing thoughts) and <strong>aside</strong> (a brief comment to the audience that others on stage don't hear). Tragedy features a <strong>tragic hero</strong> with a <strong>fatal flaw</strong> (hamartia) that leads to downfall. Shakespeare wrote noble characters' lines mostly in <strong>blank verse</strong> (unrhymed iambic pentameter) and used older words: <em>thou</em> (you), <em>wherefore</em> (why), <em>hath</em> (has).",
    concepts:[
      {t:"green", title:"🗣️ Soliloquy vs aside", body:"Soliloquy: alone on stage, long, revealing inner thoughts. Aside: short, to the audience, while others are present."},
      {t:"teal", title:"⚔️ Tragic hero", body:"A great person brought down by a flaw — Othello's jealousy, Macbeth's ambition, Hamlet's hesitation."},
      {t:"gold", title:"📜 Shakespeare's language", body:"Read it aloud, sentence by sentence (not line by line), and translate key phrases into modern English."},
    ],
    examples:[
      {title:"Shakespeare's English", body:"“O Romeo, Romeo, wherefore art thou Romeo?”", answer:"<strong>Why are you Romeo?</strong> Juliet wishes he weren't from the family her family hates — she isn't asking where he is."},
      {title:"Tragic flaw", body:"What is Othello's fatal flaw?", answer:"<strong>Jealousy</strong> — combined with trusting Iago, it leads him to destroy the person he loves."},
      {title:"Stage directions", body:"“[She turns away, wiping her eyes]”", answer:"Shows the actor's movement and reveals emotion (sadness) without words — the audience sees what she won't say."},
    ],
    mistakes:["Thinking “wherefore” means “where”.","Treating the play like a novel and ignoring how it would look on stage.","Summarising scenes instead of commenting on character, theme and dramatic effect."],
    callout:{title:"Watch it", body:"Plays are meant to be seen. Watching a filmed performance of your set play makes the language and the drama come alive."},
    activity:"Translate King Lear's line into modern English: “I am a man more sinned against than sinning.”",
    activityAnswer:"Other people have wronged me more than I have wronged them.",
    examTip:"Contextual questions often ask how an actor should say or perform a line. Give the tone or action AND explain why it fits the moment.",
    keyterms:[{w:"Soliloquy",d:"A speech by a character alone on stage, revealing thoughts"},{w:"Hamartia",d:"The tragic hero's fatal flaw"},{w:"Stage directions",d:"Instructions for movement, tone and setting"}],
    quiz:[
      {q:"A speech made alone on stage to reveal thoughts is a:",opts:["Aside","Soliloquy","Dialogue","Prologue"],a:1,et:"The audience hears the character's private thoughts."},
      {q:"“Wherefore” in Shakespeare means:",opts:["Where","Why","When","Who"],a:1,et:"Wherefore = why."},
      {q:"A tragic hero's fatal flaw is called:",opts:["Catharsis","Hamartia","Soliloquy","Blank verse"],a:1,et:"Hamartia leads to the downfall."},
    ],
    conclusion:"Read a play as if you're directing it — the words, the movements and the silences all carry meaning."},

  2: {emoji:"🖋️", subtitle:"Grade 10–12 · Unpacking a poem line by line",
    illusText:"Rap and praise poetry use the same tools as the poems in your exam: rhythm, rhyme and image.",
    hook:{title:"Poetry is already in your playlist", body:"The rhymes, rhythm and wordplay in your favourite songs are poetry tools. South Africa has a strong performance tradition too — praise poets (iimbongi) and protest poets like Mzwakhe Mbuli, the “People's Poet”, performed at rallies and ceremonies. The poems in Paper 2 use the same techniques on the page."},
    intro:"Poetry analysis looks at: the <strong>speaker</strong> (not always the poet), <strong>structure</strong> (stanzas, line length, form), <strong>rhyme scheme</strong> (ABAB…), <strong>rhythm</strong> and metre, <strong>enjambment</strong> (a sentence running onto the next line) and <strong>caesura</strong> (a pause within a line), <strong>imagery</strong> and figurative language, <strong>diction</strong>, <strong>tone</strong>, <strong>mood</strong> and <strong>theme</strong>. A <strong>sonnet</strong> has 14 lines: Petrarchan (octave + sestet) or Shakespearean (three quatrains + a rhyming couplet, ABAB CDCD EFEF GG). For unseen poems, try TPCASTT: Title, Paraphrase, Connotation, Attitude, Shifts, Title again, Theme.",
    concepts:[
      {t:"green", title:"🏗️ Form and structure", body:"Line breaks, stanza breaks and the turn (volta) in a sonnet all signal shifts in thought or feeling."},
      {t:"teal", title:"🎵 Sound and rhythm", body:"Enjambment creates flow or suspense; caesura creates a pause for emphasis. Rhyme links ideas and makes lines memorable."},
      {t:"gold", title:"🔁 TPCASTT", body:"A step-by-step method so you never freeze on an unseen poem."},
    ],
    examples:[
      {title:"Rhyme scheme", body:"What is the rhyme scheme of a Shakespearean sonnet?", answer:"<strong>ABAB CDCD EFEF GG</strong> — three quatrains and a final rhyming couplet."},
      {title:"Enjambment", body:"Why might a poet let a sentence run over a line break?", answer:"To create <strong>flow or suspense</strong> — the reader is pulled to the next line, often onto a surprising word."},
      {title:"A shift", body:"A poem describes a peaceful village for eight lines, then line 9 begins “But”.", answer:"“But” marks a <strong>shift (volta)</strong> in tone — from peace to tension or loss."},
    ],
    mistakes:["Assuming the speaker is the poet.","Listing devices without explaining their effect.","Paraphrasing the whole poem instead of analysing short quotations."],
    callout:{title:"Read it aloud", body:"Poems are written for the ear. Reading aloud reveals rhythm, rhyme and where the pauses fall."},
    activity:"Work out the rhyme scheme: “The taxi hoots before the light, / the hawkers set their tables out, / the city shakes off sleepy night, / and Monday starts its busy shout.”",
    activityAnswer:"<strong>ABAB</strong> (light / night; out / shout).",
    examTip:"Quote short phrases — one to five words — and explain their effect. Never copy whole stanzas.",
    keyterms:[{w:"Enjambment",d:"A sentence that runs on from one line to the next"},{w:"Sonnet",d:"A 14-line poem with a set rhyme scheme"},{w:"Volta",d:"A turn or shift in thought in a poem"}],
    quiz:[
      {q:"A sonnet has:",opts:["10 lines","12 lines","14 lines","16 lines"],a:2,et:"Always 14 lines."},
      {q:"When a sentence runs on to the next line without punctuation, it is:",opts:["Caesura","Enjambment","Refrain","Rhyme"],a:1,et:"The sense carries over the line break."},
      {q:"A Shakespearean sonnet ends with a:",opts:["Rhyming couplet","Sestet","Limerick","Refrain"],a:0,et:"The final GG lines."},
    ],
    conclusion:"Poems are compressed. Slow down, read aloud, and explain what each choice does."},

  3: {emoji:"📝", subtitle:"Grade 10–12 · Big ideas in a few pages",
    illusText:"A safari is a holiday for tourists. For one family fleeing war, the same park is a deadly journey.",
    hook:{title:"The Ultimate Safari", body:"In Nadine Gordimer's short story “The Ultimate Safari”, a young girl tells how her family flees the war in Mozambique on foot through the Kruger National Park to reach a refugee camp in South Africa. Tourists pay for safaris in the same park. In a few pages, the story makes you see one place through two completely different lives."},
    intro:"Short stories focus on <strong>one main conflict</strong>, a few characters and a limited setting. Every detail counts. Look for the <strong>narrator</strong> and point of view, the <strong>title</strong> (often ironic or symbolic), the <strong>epiphany</strong> (a sudden realisation), a <strong>twist</strong> or <strong>open ending</strong>, and how setting and symbols carry the theme.",
    concepts:[
      {t:"green", title:"✂️ Economy", body:"There's no space for extra scenes, so every image, name and line of dialogue was chosen for a reason."},
      {t:"teal", title:"💡 Epiphany and twist", body:"Many stories turn on one moment of realisation — for a character, or for the reader."},
      {t:"gold", title:"🏷️ The title", body:"Ask what the title means literally, and what it means once you've finished the story."},
    ],
    examples:[
      {title:"Ironic title", body:"Why is “The Ultimate Safari” ironic?", answer:"A safari suggests a luxury holiday, but for the refugees the park is a <strong>dangerous journey for survival</strong>. The title contrasts tourists' pleasure with refugees' suffering."},
      {title:"The narrator", body:"What is the effect of a child narrator?", answer:"Her <strong>simple, honest language</strong> makes the horrors more moving — she reports events without fully understanding them."},
      {title:"Epiphany", body:"What is an epiphany?", answer:"A <strong>sudden moment of realisation</strong> that changes how a character (or the reader) understands their situation."},
    ],
    mistakes:["Ignoring the title.","Ignoring who narrates the story and why.","Confusing the author with the narrator."],
    callout:{title:"Read twice", body:"Short stories reward re-reading. The second time, you'll notice the foreshadowing and symbols you missed."},
    activity:"Write a six-sentence story with a twist ending.",
    activityAnswer:"Answers will vary. Check for a clear set-up, a single conflict and a final sentence that changes how the reader understands the story.",
    examTip:"Title questions want both the literal meaning AND the deeper or ironic meaning, linked to the story's theme.",
    keyterms:[{w:"Epiphany",d:"A sudden moment of realisation"},{w:"Open ending",d:"An ending that leaves questions unresolved"},{w:"Irony",d:"A contrast between expectation and reality"}],
    quiz:[
      {q:"A sudden moment of realisation for a character is an:",opts:["Epiphany","Exposition","Elegy","Euphemism"],a:0,et:"It often changes the character."},
      {q:"In “The Ultimate Safari”, the title is:",opts:["Literal only","Ironic","Meaningless","A simile"],a:1,et:"The journey is the opposite of a holiday."},
      {q:"Short stories usually have:",opts:["Many subplots","A single main conflict","No characters","No setting"],a:1,et:"They focus on one conflict."},
    ],
    conclusion:"Short stories say a lot in little space. Read every detail as if it was chosen on purpose — because it was."},

  4: {emoji:"🇿🇦", subtitle:"Grade 10–12 · Our stories, our voices",
    illusText:"In 1994, a new President read a poem written after Sharpeville to the first democratic Parliament.",
    hook:{title:"A poem at the opening of Parliament", body:"On 24 May 1994, in his first State of the Nation Address, President Nelson Mandela read Ingrid Jonker's poem “The child who was shot dead by soldiers at Nyanga”, written after the Sharpeville massacre of 1960. A poem written in grief became part of a nation's new beginning. That's the power of South African literature: it records our history and helps us imagine our future."},
    intro:"South African literature includes <strong>oral traditions</strong> such as <em>izibongo</em> (praise poetry) and folktales; <strong>resistance writing</strong>, like the 1950s Sophiatown writers of <em>Drum</em> magazine (Can Themba wrote “The Suit”) and the Black Consciousness poets of the 1970s (Mongane Wally Serote, Sipho Sepamla); and <strong>post-1994 writing</strong> about identity, memory and reconciliation, such as Antjie Krog's <em>Country of My Skull</em> about the Truth and Reconciliation Commission. Knowing the context helps you understand why a text was written — but your marks come from analysing the text itself.",
    concepts:[
      {t:"green", title:"🥁 Oral tradition", body:"Izibongo use praise names, repetition, metaphor and rhythm to honour people and record history — performed, not just read."},
      {t:"teal", title:"✊ Resistance writing", body:"Writing under apartheid often used irony, symbolism and everyday stories to expose injustice."},
      {t:"gold", title:"🕊️ Post-1994 voices", body:"Truth, memory, identity, belonging and the gap between promise and reality."},
    ],
    examples:[
      {title:"Why context matters", body:"Why read Can Themba's “The Suit” knowing about Sophiatown?", answer:"The story is set in <strong>Sophiatown</strong>, a vibrant community destroyed by forced removals from 1955. Knowing this deepens the reader's sense of the setting and the losses behind the story."},
      {title:"Praise poetry", body:"Name two features of izibongo.", answer:"<strong>Praise names</strong> and <strong>repetition</strong> (also metaphor, rhythm and direct address)."},
      {title:"Post-1994 themes", body:"What does <em>Country of My Skull</em> deal with?", answer:"The <strong>Truth and Reconciliation Commission</strong> — testimonies of apartheid-era crimes and the struggle to face the truth."},
    ],
    mistakes:["Writing about history and forgetting to analyse the text.","Assuming all South African literature is about apartheid.","Using stereotypes instead of the text's actual characters."],
    callout:{title:"Your community's stories", body:"Elders, praise singers and storytellers carry literature too. Recording and analysing a family story uses the same skills as Paper 2."},
    activity:"Ask an elder about a praise poem, song or story they know. Write it down and identify two literary devices in it.",
    activityAnswer:"Answers vary. Common devices: repetition, praise names, metaphor, personification and rhythm.",
    examTip:"Use context in one sentence, then link it to a specific quotation and explain the effect. Context supports analysis; it doesn't replace it.",
    keyterms:[{w:"Izibongo",d:"Praise poetry in the Nguni oral tradition"},{w:"Protest literature",d:"Writing that challenges injustice"},{w:"Context",d:"The historical and social background of a text"}],
    quiz:[
      {q:"Izibongo are:",opts:["Praise poems","Novels","Newspaper reports","Plays"],a:0,et:"An oral praise-poetry tradition."},
      {q:"<em>Drum</em> magazine in the 1950s is linked to:",opts:["The Sophiatown writers","Shakespeare","The TRC","Day Zero"],a:0,et:"Can Themba and others wrote for Drum."},
      {q:"Antjie Krog's <em>Country of My Skull</em> is about:",opts:["The Truth and Reconciliation Commission","The Anglo-Boer War","The 2010 World Cup","Load shedding"],a:0,et:"She reported on the TRC hearings."},
    ],
    conclusion:"South African literature is our memory and our argument with ourselves. Read it in context, analyse it on the page."},

  5: {emoji:"🎯", subtitle:"Grade 11–12 · Scoring every mark on extracts",
    illusText:"A (3)-mark question answered with one line earns one mark — at best.",
    hook:{title:"Why a 3-mark answer got 1", body:"The question asks: “Discuss what this extract reveals about the old man's state of mind. (3)” A learner writes: “He is sad.” One mark, maybe. Another writes: “He is anxious and lost — he keeps asking strangers for directions and his hands shake as he holds the letter, showing how unfamiliar and frightening the city is to him.” Three marks. Same knowledge — different technique."},
    intro:"Contextual questions give you an extract and ask about it and the whole text. Read the extract twice. Note the <strong>mark allocation</strong> and the <strong>question word</strong>: <em>identify/name</em> (short answer), <em>describe</em> (details), <em>explain</em> (reasons), <em>discuss</em> or <em>critically comment</em> (a developed view with evidence), <em>do you agree?</em> (a clear stand plus justification). “Place the extract in context” means explain what happened just before it.",
    concepts:[
      {t:"green", title:"🔢 Marks guide length", body:"(1) = one fact. (2) = two points. (3) = a developed point with evidence and explanation."},
      {t:"teal", title:"🪜 The question-word ladder", body:"Identify → describe → explain → discuss → evaluate. Each step up needs more reasoning."},
      {t:"gold", title:"🙋 Opinion questions", body:"“Do you agree?” — state yes or no, then justify with evidence from the text. A bare “Yes” earns nothing."},
    ],
    examples:[
      {title:"Context question", body:"“Describe the time and place of this extract. (2)”", answer:"Give <strong>both</strong>: e.g. “It is night (1) in the shebeen in Sophiatown (1).”"},
      {title:"Explain question", body:"“Explain what this line reveals about the speaker. (2)”", answer:"Give the quality plus the evidence: e.g. “She is defiant — she refuses to apologise even when threatened.”"},
      {title:"Opinion question", body:"“Do you agree that the father is a sympathetic character? Discuss. (3)”", answer:"State your view, then give two reasons from the text: “Yes. Although he is strict, he travels far to find his son and forgives him, which shows his love.”"},
    ],
    mistakes:["No clear stand in an opinion question.","Quoting long passages instead of answering.","Answering from the film or a summary instead of the text."],
    callout:{title:"Use the extract", body:"If the question says “refer to lines 5–8”, your answer must come from those lines. Quote briefly and explain."},
    activity:"Practise mark matching: for the question “Explain why the speaker is angry. (2)”, write an answer with exactly two clear points.",
    activityAnswer:"Example: “The speaker is angry because he was blamed for the theft (1) and because his friend failed to defend him (1).”",
    examTip:"For “discuss” questions, a one-word answer earns 0. State your view, then support it with evidence from the text.",
    keyterms:[{w:"Extract",d:"A passage taken from a larger text"},{w:"Context",d:"What happens around the extract in the text"},{w:"Justify",d:"Give reasons and evidence for your view"}],
    quiz:[
      {q:"“Quote a word that shows…” requires:",opts:["Your own words","The exact word in inverted commas","A paragraph","Nothing"],a:1,et:"Copy the exact word."},
      {q:"A (3)-mark “discuss” question needs:",opts:["One word","A view plus developed reasons","Only a quotation","A summary of the book"],a:1,et:"Develop your view with evidence."},
      {q:"“Place this extract in context” asks you to:",opts:["Give the book's price","Explain what happened just before it","Define a word","Write a poem"],a:1,et:"Show where it fits in the story."},
    ],
    conclusion:"Contextual questions reward method: read the marks, read the question word, answer with evidence."},
};

